class Task:
    def __init__(self, id, e, p):
        self.id = id
        self.e = e  # worst-case execution cost
        self.p = p  # period
        self.u = e / p # utilization
        self.r = 0  # worst-case response time (to be calculated)

def calculate_utilization(task_i):
    return task_i.e / task_i.p

class Resource:
    def __init__(self, id):
        self.id = id

class Task:
