class Task:
    # ... (previous Task definition)
    def __init__(self, id, e, p, assigned_processor, priority):
        super().__init__(id, e, p)
        self.assigned_processor = assigned_processor
        self.priority = priority
        self.b_l = 0 # local pi-blocking
        self.b_r = 0 # remote pi-blocking

def check_priority_inversion(job_i, current_time, processor_state):
    if job_i.is_pending() and not processor_state.is_scheduled(job_i.assigned_processor, job_i.priority):
        # Priority inversion detected
        return True
    return False

class BlockingFraction:
    def __init__(self, task_x_id, resource_q_id, request_v_id, L_x_q):
        self.task_x_id = task_x_id
        self.resource_q_id = resource_q_id
        self.request_v_id = request_v_id
        self.L_x_q = L_x_q
        self.X_total = 0.0 # Represents X_x_q_v
        self.X_D = 0.0
        self.X_I = 0.0
        self.X_P = 0.0

    def calculate_fraction(self, actual_blocking_time):
        if self.L_x_q > 0:
            self.X_total = min(1.0, actual_blocking_time / self.L_x_q)
        else:
            self.X_total = 0.0
        return self.X_total

class Processor:
