class Task:
    # ... (previous Task definition)
    def calculate_N_P_k(self, processor_k_id, processor_map):
        N_i_P_k = 0
        for q_id in processor_map[processor_k_id].local_resources:
            N_i_P_k += self.N_q.get(q_id, 0)
        return N_i_P_k

def add_constraint_mutual_exclusivity(lp_solver, blocking_fraction_vars):
    for bf_var in blocking_fraction_vars:
        # bf_var.X_D, bf_var.X_I, bf_var.X_P are LP variables
        lp_solver.add_constraint(bf_var.X_D + bf_var.X_I + bf_var.X_P <= 1.0)

def add_constraint_no_remote_preemption(lp_solver, blocking_fraction_vars, task_i):
    for bf_var in blocking_fraction_vars:
        # Assuming bf_var has attributes like resource_q_id and task_x_id
        if bf_var.resource_q_id in task_i.rr_resources:
            lp_solver.add_constraint(bf_var.X_P == 0.0)

def add_constraint_local_lower_priority_preemption(lp_solver, blocking_fraction_vars, task_i, task_set, r_values):
    sum_xp_local_lower_priority = 0
    for task_x in task_set:
        if task_x.assigned_processor == task_i.assigned_processor and task_x.priority > task_i.priority:
            # task_x is in tau_ll
            for q_id in task_x.lr_resources: # Only local resources can cause local preemption
                # Sum over all requests v for q by task_x
                # N_i_x_q is the coefficient for the sum, representing max requests
                N_i_x_q_coeff = math.ceil((r_values[task_i.id] + r_values[task_x.id]) / task_x.p) * task_x.N_q.get(q_id, 0)
                for v in range(1, int(N_i_x_q_coeff) + 1):
                    # Assuming lp_solver.get_variable returns the LP variable object
                    sum_xp_local_lower_priority += lp_solver.get_variable(f'X_P_{task_x.id}_{q_id}_{v}')

    sum_Ni_u_remote = 0
    for u_id in task_i.rr_resources:
        sum_Ni_u_remote += task_i.N_q.get(u_id, 0)

    lp_solver.add_constraint(sum_xp_local_lower_priority <= 1 + sum_Ni_u_remote)

def check_dfly_lemma1(request_i, task_x, schedule):
    delaying_requests = []
    for request_x in task_x.get_all_requests():
        if schedule.does_request_x_delay_request_i(request_x, request_i):
            delaying_requests.append(request_x)

    # This lemma states that len(delaying_requests) <= 1
    assert len(delaying_requests) <= 1, "DFLP Lemma 1 violated!"
    return True

def add_constraint_dfly_direct_delay(lp_solver, blocking_fraction_vars, task_i, task_set, resource_map, r_values):
    for q_id in resource_map.keys():
        if task_i.N_q.get(q_id, 0) == 0: continue # J_i doesn't access q, so no direct delay

        for task_x in task_set:
            if task_x.id == task_i.id: continue

            sum_xd_x_q_v = 0
            N_i_x_q_coeff = math.ceil((r_values[task_i.id] + r_values[task_x.id]) / task_x.p) * task_x.N_q.get(q_id, 0)
            for v in range(1, int(N_i_x_q_coeff) + 1):
                sum_xd_x_q_v += lp_solver.get_variable(f'X_D_{task_x.id}_{q_id}_{v}')

            lp_solver.add_constraint(sum_xd_x_q_v <= task_i.N_q.get(q_id, 0))

def add_constraint_dfly_direct_indirect_delay(lp_solver, blocking_fraction_vars, task_i, task_set, processor_map, r_values):
    for p_k_id in processor_map.keys():
        N_i_P_k_val = task_i.calculate_N_P_k(p_k_id, processor_map)
        if N_i_P_k_val == 0: continue

        for task_x in task_set:
            if task_x.id == task_i.id: continue

            sum_xd_xi_x_q_v = 0
            for q_id in processor_map[p_k_id].local_resources:
                N_i_x_q_coeff = math.ceil((r_values[task_i.id] + r_values[task_x.id]) / task_x.p) * task_x.N_q.get(q_id, 0)
                for v in range(1, int(N_i_x_q_coeff) + 1):
                    sum_xd_xi_x_q_v += lp_solver.get_variable(f'X_D_{task_x.id}_{q_id}_{v}') + \
                                       lp_solver.get_variable(f'X_I_{task_x.id}_{q_id}_{v}')

            lp_solver.add_constraint(sum_xd_xi_x_q_v <= N_i_P_k_val)

class Task:
    # ... (previous Task definition)
    def calculate_pc_tau_i(self, all_tasks, all_resources):
        self.pc_resources = set()
        for q_id in all_resources.keys():
            for task_x in all_tasks:
                # Assuming task_x.priority < self.priority means higher priority
                if task_x.priority <= self.priority and task_x.N_q.get(q_id, 0) > 0:
                    self.pc_resources.add(q_id)
                    break

    def calculate_pc_tau_i_P_k(self, p_k_id, processor_map):
        pc_P_k = set()
        for q_id in self.pc_resources:
            if q_id in processor_map[p_k_id].local_resources:
                pc_P_k.add(q_id)
        return pc_P_k

def add_constraint_dpcp_no_non_conflicting_delay(lp_solver, blocking_fraction_vars, task_i, all_resources):
    for bf_var in blocking_fraction_vars:
        q_id = bf_var.resource_q_id
        if q_id not in task_i.pc_resources:
            lp_solver.add_constraint(bf_var.X_D + bf_var.X_I == 0.0)

def add_constraint_dpcp_ceiling_blocking(lp_solver, blocking_fraction_vars, task_i, task_set, processor_map, r_values):
    for p_k_id in processor_map.keys():
        N_i_P_k_val = task_i.calculate_N_P_k(p_k_id, processor_map)
        if N_i_P_k_val == 0: continue

        sum_xd_xi_lower_priority = 0
        # Assuming task_i.pc_resources_P_k is a map from p_k_id to a set of q_ids
        for q_id in task_i.pc_resources_P_k.get(p_k_id, set()): 
            for task_x in task_set:
                if task_x.priority > task_i.priority: # Lower priority tasks
                    N_i_x_q_coeff = math.ceil((r_values[task_i.id] + r_values[task_x.id]) / task_x.p) * task_x.N_q.get(q_id, 0)
                    for v in range(1, int(N_i_x_q_coeff) + 1):
                        sum_xd_xi_lower_priority += lp_solver.get_variable(f'X_D_{task_x.id}_{q_id}_{v}') + \
                                                    lp_solver.get_variable(f'X_I_{task_x.id}_{q_id}_{v}')

        lp_solver.add_constraint(sum_xd_xi_lower_priority <= N_i_P_k_val)

import math

def calculate_dpcp_wait_times(task_i, q_id, task_set, resource_map, r_values, processor_map):
    P_q_id = resource_map[q_id].assigned_processor
    pc_tau_i_P_q = task_i.calculate_pc_tau_i_P_k(P_q_id, processor_map)

    # Calculate W_L_i_q
    W_L_i_q = 0
    for task_x in task_set:
        if task_x.priority > task_i.priority: # Lower priority
            for v_id in pc_tau_i_P_q:
                W_L_i_q = max(W_L_i_q, task_x.L_q.get(v_id, 0))

    # Calculate W_H_i_q iteratively
    W_i_q_current = W_L_i_q + task_i.L_q.get(q_id, 0) # Initial W_i_q without W_H_i_q
    W_H_i_q_prev = 0
    W_H_i_q_current = 0

    while W_H_i_q_current != W_H_i_q_prev:
        W_H_i_q_prev = W_H_i_q_current
        demand_higher_priority = 0
        for task_x in task_set:
            if task_x.priority < task_i.priority: # Higher priority
                sum_Nx_y_Lx_y = 0
                for y_id in pc_tau_i_P_q:
                    sum_Nx_y_Lx_y += task_x.N_q.get(y_id, 0) * task_x.L_q.get(y_id, 0)
                demand_higher_priority += math.ceil((r_values[task_x.id] + W_i_q_current) / task_x.p) * sum_Nx_y_Lx_y
        W_H_i_q_current = demand_higher_priority
        W_i_q_current = W_L_i_q + W_H_i_q_current + task_i.L_q.get(q_id, 0)

    W_i_q = W_i_q_current

    # Calculate D_x_y_i_q for all x, y
    D_x_y_i_q_map = {}
    for task_x in task_set:
        D_x_y_i_q_map[task_x.id] = {}
        for y_id in resource_map.keys():
            D_x_y_i_q_map[task_x.id][y_id] = math.ceil((r_values[task_x.id] + W_i_q) / task_x.p) * task_x.N_q.get(y_id, 0)

    return W_i_q, W_L_i_q, W_H_i_q, D_x_y_i_q_map
